import re
seq = "".join(l for l in open("region.fasta") if not l.startswith(">")).replace("\n","")
n=len(seq)

# All occurrences of the 9-mer core of the repeat
for pat in ["GTTCCCCGC","GTTCCCCCGC"]:
    print(pat, [m.start()+1 for m in re.finditer("(?="+pat+")", seq)])

# inverted repeats / palindromes >= 8 (excluding CRISPR)
# simple: find palindromic words length 8-12
def pals(seq, lo=8, hi=12):
    out=[]
    for L in range(lo,hi+1):
        for i in range(0,n-L+1):
            w=seq[i:i+L]
            if w==w.translate(str.maketrans("ACGT","TGCA"))[::-1]:
                out.append((i+1,w))
    return out
p=pals(seq)
print("\nPalindromes 8-12 (count %d):"%len(p))
for x in p[:40]: print("  ",x)

# long homopolymer runs
print("\nHomopolymer runs >=5:")
for m in re.finditer(r"(A{5,}|T{5,}|G{5,}|C{5,})", seq):
    print("  ", m.start()+1, m.group())

# dinucleotide tandem repeats
print("\nTandem di-nucleotide repeats >=8 units:")
for m in re.finditer(r"(?=(([ACGT]{2})\2{7,}))", seq):
    print("  ", m.start()+1, m.group(1)[:30])
